val DT = 1.0 / 60
var prev = System.nanoTime()
var lag = 0.0
while (running) {
  val now = System.nanoTime()
  lag += (now - prev) / 1e9; prev = now      // monotonic source
  if (lag > 0.25) lag = 0.25                 // clamp: no spiral of death
  drainInput()
  while (lag >= DT) { world.step(DT); lag -= DT }
  render(lag / DT)
  Thread.sleep(1L)                           // coarse; re-measured above
}
